questionvariables.text:
/* Randomise backwards: choose c, n, then a misconception (or "correct"). */
n : rand(5)+2;                         /* exponent 2..6 */
m : n-1;
c : rand_with_prohib(2,9,[n]);         /* positive 2..9, c != n for clean display */
notn : rand(3)+1;                       /* 1: f'(x)  2: dy/dx  3: Leibniz */
errtype : rand(5)+1;                    /* 1 keepexp 2 nomult 3 incpow 4 dropc 5 correct */
is_ok : is(errtype = 5);

expr : c*x^n;
ta1  : c*n*x^m;                         /* the TRUE derivative */

/* Simplified final answers (Line 2) for each variant. */
final_keepexp : c*n*x^n;
final_nomult  : c*x^m;
final_incpow  : c*n*x^(n+1);
final_dropc   : n*x^m;
final_correct : ta1;

/* Error tag (bare atom), the shown final, and a human-readable name. */
if errtype = 1 then ( errtag : keepexp, buggy_final : final_keepexp,
    err_name : "the exponent was not reduced by 1, so the power stayed the same." )
elseif errtype = 2 then ( errtag : nomult, buggy_final : final_nomult,
    err_name : "the power was not brought down as a multiplying factor." )
elseif errtype = 3 then ( errtag : incpow, buggy_final : final_incpow,
    err_name : "the exponent was increased by 1 instead of decreased (raising the power is integration, not differentiation)." )
elseif errtype = 4 then ( errtag : dropc, buggy_final : final_dropc,
    err_name : "the constant multiple was dropped." )
else ( errtag : nowrong, buggy_final : final_correct, err_name : "" );

/* Unevaluated Line-1 forms (built with simp OFF so 9.4.x^(4-1) shows the working).
   The L1s selection MUST run under simp:false too - assigning it while simp is on
   re-simplifies 9*4*x^4 back to 36*x^4. Use is() because "=" is not a boolean when
   simp is off. */
simp:false;
L1_keepexp : c*n*x^n;
L1_nomult  : c*x^(n-1);
L1_incpow  : c*n*x^(n+1);
L1_dropc   : n*x^(n-1);
L1_correct : c*n*x^(n-1);
step_disp  : c*n*x^(n-1);              /* rule-application line for the worked solution */
if is(errtype=1) then L1s : L1_keepexp
elseif is(errtype=2) then L1s : L1_nomult
elseif is(errtype=3) then L1s : L1_incpow
elseif is(errtype=4) then L1s : L1_dropc
else L1s : L1_correct;
simp:true;

/* Radio options: values are bare atoms; display strings render as plain text
   (input option casstring). Shuffle the order and record it in the question note. */
opts : [[keepexp, is(errtag=keepexp), "The exponent was not reduced by 1"],
        [nomult,  is(errtag=nomult),  "The power was not brought down as a multiplying factor"],
        [incpow,  is(errtag=incpow),  "The exponent was increased instead of decreased"],
        [dropc,   is(errtag=dropc),   "The constant multiple was dropped"],
        [nowrong, is(errtag=nowrong), "Nothing is wrong: the differentiation is correct"]];
diag_ta : random_permutation(opts);
opt_order : maplist(first, diag_ta);
